// Generated by AI (UnitTest MCP)
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

const extensionRoot = join(dirname(fileURLToPath(import.meta.url)), "..");

const manifest = JSON.parse(readFileSync(join(extensionRoot, "package.json"), "utf8"));
const source = readFileSync(join(extensionRoot, "src/extension.ts"), "utf8");

const contributed: string[] = manifest.contributes.commands.map(
  (entry: { command: string }) => entry.command
);

const paletteEntries: { command: string; when?: string }[] =
  manifest.contributes.menus?.commandPalette ?? [];

const hidden = new Set(
  paletteEntries.filter((entry) => entry.when === "false").map((entry) => entry.command)
);

/**
 * A command whose handler declares an `item`/`node` parameter is driven by a
 * view row. Registered handlers accept it as optional and, given nothing, only
 * warn — `requireItem` answers "Run <action> from an Intent Board row."
 */
const viewScoped = () => {
  const pattern = /registerCommand\(\s*"(mindleak\.[a-zA-Z.]+)",\s*(?:async\s*)?\(([^)]*)\)/g;
  const found: string[] = [];
  for (const match of source.matchAll(pattern)) {
    if (/item|node/.test(match[2])) found.push(match[1]);
  }
  return found;
};

const isRefresh = (command: string) => /\.refresh$/.test(command) || command === "mindleak.refresh";

describe("command palette surface", () => {
  /**
   * The palette listed all 34 commands, 26 of which could do nothing from
   * there. Typing "MindLeak" returned an undifferentiated wall, and two thirds
   * of it answered "not from here". Asserted as a rule rather than a list so a
   * new row-driven command is caught rather than quietly rejoining the wall.
   */
  it("hides every command that needs a view row", () => {
    const exposed = viewScoped().filter((command) => !hidden.has(command));

    expect(exposed).toEqual([]);
  });

  it("hides per-view refresh, which belongs on the view title", () => {
    const exposed = contributed.filter((command) => isRefresh(command) && !hidden.has(command));

    expect(exposed).toEqual([]);
  });

  /**
   * A budget, not a preference. Nothing else in the repository treats the size
   * of a user-facing surface as a cost, which is how it reached 34 without
   * anyone deciding to (ADR-0059 makes the same argument about the MCP tools).
   * Raising this number is allowed; doing it without noticing is not.
   */
  it("keeps the palette small enough to read", () => {
    const visible = contributed.filter((command) => !hidden.has(command));

    expect(visible.length).toBeLessThanOrEqual(10);
  });

  it("never hides a command it does not contribute", () => {
    const orphaned = [...hidden].filter((command) => !contributed.includes(command));

    expect(orphaned).toEqual([]);
  });

  /**
   * Guards the guard: if the scrape stops matching, every assertion above
   * passes vacuously while the palette quietly refills.
   */
  it("still recognises the row-driven commands it is meant to police", () => {
    expect(viewScoped().length).toBeGreaterThan(15);
  });
});
